  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 The Romantic Poets: Wordsworth and Blake$j$, $j${"readings": [{"title": "Psalm 104 (King James Version)", "url": "/portal/bible/Psalms/104"}], "body": "Romanticism, which flourished in Britain from about 1790 to 1850, was a movement that valued emotion, imagination and nature over the cool reason of the Enlightenment. William Wordsworth and Samuel Taylor Coleridge published Lyrical Ballads in 1798. In the preface, Wordsworth described poetry as the spontaneous overflow of powerful feelings, written in the language of ordinary people.\n\nWordsworth's poem I Wandered Lonely as a Cloud begins with a simile and describes a field of daffodils whose memory later fills his heart with joy. Notice the pattern: an experience in nature, then reflection on its lasting effect. Nature in Romantic poetry is a teacher and a comfort.\n\nWilliam Blake wrote and illustrated his own books. Songs of Innocence, published in 1789, and Songs of Experience, published in 1794, show two views of the world. In The Lamb, a child asks who made the gentle lamb, and the answer is the one who is called by the lamb's own name, a clear echo of Christ. In The Tyger, the speaker is awed by a fearsome creature and asks, Did he who made the Lamb make thee? The question holds together beauty, danger and the mystery of the Creator.\n\nScripture sees God in creation. Psalm 8:3 and 4 says that when I consider thy heavens, the work of thy fingers, I ask, What is man, that thou art mindful of him?\n\nYour task: (1) Explain what Romantic poets valued. (2) Compare the tone of The Lamb and The Tyger. (3) Connect one Romantic poem to Psalm 8.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.3.2", "script": "Welcome to the Romantic period. Listen, from about 1790 to 1850, British poets turned from the cool reason of the Enlightenment to emotion, imagination and nature.\n\nNow watch this. William Wordsworth and Samuel Taylor Coleridge published Lyrical Ballads in 1798. In the preface, Wordsworth said that poetry is the spontaneous overflow of powerful feelings, written in the language of ordinary people. His poem I Wandered Lonely as a Cloud opens with a simile and describes a field of daffodils. Later, in a quiet hour, the memory of that field fills his heart with joy. Nature is a teacher and a comfort.\n\nLook at William Blake, who wrote and illustrated his own books. Songs of Innocence, 1789, and Songs of Experience, 1794, show two views of the world. In The Lamb, a child asks who made the gentle lamb, and the answer points to Christ. In The Tyger, the speaker stands in awe of a fearsome creature and asks, Did he who made the Lamb make thee? Beauty, danger and mystery in one question.\n\nScripture sees God in creation, too. Psalm 8, when I consider thy heavens, the work of thy fingers. Your task is to explain what Romantics valued, compare the tone of the two Blake poems, and connect a poem to Psalm 8. Take the four question check. Look up. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 The Romantic Poets: Wordsworth and Blake$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Gothic Fiction and Mary Shelley's Frankenstein$j$, $j${"readings": [{"title": "Mark 12 (King James Version)", "url": "/portal/bible/Mark/12"}], "body": "Gothic fiction uses dark settings, mystery and fear to explore human nature. Mary Shelley began Frankenstein in the summer of 1816, when she was eighteen, during a stay near Lake Geneva with friends who challenged each other to write ghost stories. The novel was published in 1818, with the subtitle The Modern Prometheus.\n\nThe book uses a frame narrative. Captain Walton writes letters about his Arctic voyage, and in them he tells the story of Victor Frankenstein, a young scientist who creates a living being from lifeless matter. Horrified by his work, Victor abandons the creature. The creature, intelligent and lonely, learns to speak and read, longs for companionship and is rejected by everyone he meets. Bitter, he turns to revenge, and both creator and creation are destroyed.\n\nLook at the themes. The first is responsibility: Victor made a life and refused to care for it. The second is ambition without wisdom, similar to Macbeth's. The third is isolation and the human need to belong.\n\nThe novel raises a question that is still debated: when people create powerful tools, who is responsible for the results? Scripture gives a standard of care, found in Mark 12:31, thou shalt love thy neighbour as thyself.\n\nYour task: (1) Explain the frame narrative. (2) State two themes and give one detail for each. (3) Describe how Victor failed in his responsibility, and relate it to Mark 12:31.\n\nFlorida standards: ELA.12.R.1.1, ELA.12.R.1.2, ELA.12.R.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.1, ELA.12.R.1.2, ELA.12.R.1.3", "script": "Now let's step into the Gothic. Listen, Gothic fiction uses dark settings, mystery and fear to explore human nature, and the most famous Gothic novel in English was written by a teenager.\n\nMary Shelley began Frankenstein in the summer of 1816, when she was eighteen. She was staying near Lake Geneva with friends, and they challenged one another to write ghost stories. The novel was published in 1818 with the subtitle The Modern Prometheus.\n\nNow watch this. It uses a frame narrative. Captain Walton writes letters about his Arctic voyage, and in them he tells the story of Victor Frankenstein, a young scientist who creates a living being. Victor is horrified at what he has made, and he abandons it. The creature is intelligent and lonely. He learns to speak and read, he longs for a friend, and everyone rejects him. Bitter, he turns to revenge, and creator and creation are both destroyed.\n\nLook at the themes. Responsibility. Victor made a life and refused to care for it. Ambition without wisdom. And the human need to belong. Scripture sets the standard in Mark 12:31, thou shalt love thy neighbour as thyself.\n\nYour task is to explain the frame narrative, state two themes, and describe how Victor failed in his responsibility. Take the four question check. Care for what you create. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Gothic Fiction and Mary Shelley's Frankenstein$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Charles Dickens and the Social Conscience$j$, $j${"readings": [{"title": "Luke 3 (King James Version)", "url": "/portal/bible/Luke/3"}], "body": "Queen Victoria reigned from 1837 to 1901, and the Victorian age saw factories, railways, crowded cities and great wealth beside great poverty. The most popular novelist of the age was Charles Dickens. As a boy of twelve, he worked pasting labels on bottles in a factory while his father was in a debtors' prison. He never forgot it, and his novels give a voice to the poor and the powerless.\n\nOliver Twist, published in installments from 1837, follows an orphan in a workhouse who dares to ask for more food. Great Expectations, published in 1861, follows Pip, a poor boy who comes into money and learns the cost of pride and the value of loyalty. A Christmas Carol, published in 1843, tells of Ebenezer Scrooge, a hard man visited by the ghosts of Christmas Past, Present and Yet to Come. Scrooge changes, becomes generous and keeps Christmas well. Tiny Tim's words, God bless us, every one, close the story.\n\nDickens uses vivid characters, humor, irony and detailed settings to make readers feel what poverty is like. He is a social critic, using fiction to press for change.\n\nScripture teaches care for those in need. Luke 3:11 says, He that hath two coats, let him impart to him that hath none; and he that hath meat, let him do likewise.\n\nYour task: (1) Explain how Dickens's childhood shaped his writing. (2) Describe Scrooge's change in three sentences. (3) Connect Scrooge's lesson to Luke 3:11.\n\nFlorida standards: ELA.12.R.1.3, ELA.12.R.1.2, ELA.12.R.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.3, ELA.12.R.1.2, ELA.12.R.3.2", "script": "Welcome to the Victorian age. Listen, Queen Victoria reigned from 1837 to 1901, and in those years Britain saw factories, railways, crowded cities, and great wealth standing right beside great poverty.\n\nThe most popular novelist of the day was Charles Dickens. When he was twelve, his father was sent to a debtors' prison, and Charles went to work pasting labels on bottles in a factory. He never forgot it. His novels give voice to the poor and the powerless.\n\nNow watch this. Oliver Twist follows an orphan in a workhouse who dares to ask for more food. Great Expectations, published in 1861, follows Pip, a poor boy who comes into money and learns the cost of pride and the value of loyalty. And A Christmas Carol, published in 1843, tells of Ebenezer Scrooge, a hard man who is visited by three ghosts. Scrooge changes. He becomes generous, and Tiny Tim says, God bless us, every one.\n\nDickens used vivid characters, humor and irony, so readers would feel what poverty is like. He was a social critic.\n\nLuke 3:11 says, He that hath two coats, let him impart to him that hath none. Your task is to explain how his childhood shaped his writing, describe Scrooge's change, and connect it to Luke. Take the four question check. Let your heart be moved. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Charles Dickens and the Social Conscience$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Victorian Poetry: Tennyson, Browning and Rossetti$j$, $j${"readings": [{"title": "2 Timothy 4 (King James Version)", "url": "/portal/bible/2Timothy/4"}], "body": "Victorian poets wrote about duty, doubt, love and faith in a changing world. Alfred, Lord Tennyson, poet laureate of Britain from 1850, wrote Ulysses, in which an aged hero longs for one more voyage. The poem ends with a resolve to strive, to seek, to find, and not to yield. It is written in blank verse and speaks to anyone who wants to keep growing.\n\nRobert Browning mastered the dramatic monologue, a poem in which one speaker addresses a listener, revealing his own character without meaning to. In My Last Duchess, published in 1842, a duke shows a visitor a portrait of his late wife and calmly reveals his pride and cruelty. The reader must read between the lines, which is an example of an unreliable speaker.\n\nElizabeth Barrett Browning wrote Sonnets from the Portuguese, published in 1850, including the famous How do I love thee? Let me count the ways. Christina Rossetti wrote devotional poems of simple, deep faith.\n\nWhen you analyze a poem, identify the speaker, listener and situation, track the tone, and decide what the poem reveals beyond what it says.\n\nPaul used a similar spirit of perseverance in 2 Timothy 4:7, I have fought a good fight, I have finished my course, I have kept the faith.\n\nYour task: (1) Define dramatic monologue and unreliable speaker. (2) Explain what My Last Duchess reveals about the duke. (3) Connect the ending of Ulysses to 2 Timothy 4:7.\n\nFlorida standards: ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.R.1.4, ELA.12.R.3.1, ELA.12.R.3.2", "script": "Now we hear the Victorian poets. Listen, they wrote about duty, doubt, love and faith in a world that was changing fast.\n\nAlfred, Lord Tennyson became poet laureate in 1850. In his poem Ulysses, an aged hero longs for one more voyage, and the poem ends with a resolve to strive, to seek, to find, and not to yield. It is blank verse, and it speaks to anyone who wants to keep growing.\n\nNow watch this. Robert Browning mastered the dramatic monologue. That is a poem in which one speaker talks to a listener and reveals his own character without meaning to. In My Last Duchess, published in 1842, a duke shows a visitor a portrait of his late wife, and calmly reveals his pride and his cruelty. The speaker is unreliable, so the reader has to read between the lines.\n\nElizabeth Barrett Browning wrote Sonnets from the Portuguese in 1850, including How do I love thee? Let me count the ways. And Christina Rossetti wrote devotional poems of simple, deep faith.\n\nTo analyze a poem, find the speaker, the listener and the situation, track the tone, and decide what it reveals beyond what it says. Paul said in 2 Timothy 4:7, I have fought a good fight, I have finished my course, I have kept the faith.\n\nYour task is to define dramatic monologue, explain what the duke reveals, and connect Ulysses to Paul. Take the four question check. Do not yield. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Victorian Poetry: Tennyson, Browning and Rossetti$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Romantic and Victorian Voices$j$, $j${"prompt": "Write a literary analysis of at least 300 words on one work or author from this unit. Use complete sentences and label each part. Philippians 4:8 says, Whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.\n\nPart 1: Introduce your choice (a Wordsworth or Blake poem, Frankenstein, a Dickens work or a Victorian poem) with a clear thesis about its theme.\nPart 2: Support your thesis with at least two pieces of evidence from the text, quoting briefly.\nPart 3: Name and explain at least two literary techniques at work (for example simile, symbol, frame narrative, irony, dramatic monologue or blank verse).\nPart 4: Explain the historical setting, either the Romantic reaction to the Enlightenment or the Victorian age of industry, and how it shapes the work.\nPart 5: Connect the theme to a passage of Scripture and write a concluding paragraph.", "rubric": "100 points. Part 1, thesis: 15 points. Part 2, evidence: 25 points. Part 3, techniques: 25 points. Part 4, setting: 15 points. Part 5, Scripture and conclusion: 15 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Romantic and Victorian Voices$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Nature, Creation and Compassion$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a place in nature where you felt close to God or at peace, (2) explains how a Romantic poem from this unit expresses a similar feeling, (3) tells what Frankenstein or A Christmas Carol teaches about responsibility and compassion, and (4) connects your answer to Matthew 25:40, which says, Verily I say unto you, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do you think writers use fiction to bring attention to social problems? Keep your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Nature, Creation and Compassion$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: The Romantic Poets: Wordsworth and Blake$j$, $j${"questions": [{"q": "Romantic poets valued:", "options": ["Emotion, imagination and nature", "Battles", "Only strict logic", "Law"]}, {"q": "Lyrical Ballads was published by:", "options": ["Dickens and Eliot", "Wordsworth and Coleridge", "Chaucer and Milton", "Pope and Swift"]}, {"q": "Blake's two paired books are:", "options": ["Paradise Lost and Paradise Regained", "Songs of Innocence and Songs of Experience", "Oliver Twist and Hard Times", "Hamlet and Macbeth"]}, {"q": "In The Tyger, the speaker asks whether:", "options": ["Gold is valuable", "The Maker of the Lamb also made the Tyger", "The Tyger is tame", "Night is long"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Romantic Poets: Wordsworth and Blake$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,1}'::int[], array[$j$Romanticism emphasized feeling and nature.$j$,$j$It appeared in 1798.$j$,$j$They show two views of the world.$j$,$j$It joins beauty, danger and the mystery of the Creator.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: The Romantic Poets: Wordsworth and Blake$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Gothic Fiction and Mary Shelley's Frankenstein$j$, $j${"questions": [{"q": "Frankenstein was published in:", "options": ["1611", "1066", "1914", "1818"]}, {"q": "Captain Walton is the:", "options": ["Creature", "King", "Narrator of the outer frame", "Scientist who creates life"]}, {"q": "A main theme of Frankenstein is:", "options": ["The joy of travel", "Farming", "Music", "Responsibility for what we create"]}, {"q": "Mark 12:31 teaches:", "options": ["Love your neighbor as yourself", "Seek revenge", "Avoid the lonely", "Trust wealth"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Gothic Fiction and Mary Shelley's Frankenstein$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,0}'::int[], array[$j$Mary Shelley's novel appeared in 1818.$j$,$j$Walton's letters frame the story.$j$,$j$Victor abandons his creation.$j$,$j$The creature needed love and care.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Gothic Fiction and Mary Shelley's Frankenstein$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Charles Dickens and the Social Conscience$j$, $j${"questions": [{"q": "Dickens as a boy worked in:", "options": ["A ship", "A bank", "A factory pasting labels", "A palace"]}, {"q": "A Christmas Carol was published in:", "options": ["1776", "1843", "1611", "1914"]}, {"q": "Scrooge is visited by:", "options": ["Two kings", "A dragon", "Three ghosts", "Four knights"]}, {"q": "Dickens is called a social critic because he:", "options": ["Wrote dictionaries", "Used fiction to expose unfairness and press for change", "Wrote only comedies", "Avoided real life"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Charles Dickens and the Social Conscience$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,2,1}'::int[], array[$j$His father was in debtors' prison.$j$,$j$It appeared in 1843.$j$,$j$Past, Present and Yet to Come.$j$,$j$His novels speak for the poor.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Charles Dickens and the Social Conscience$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Victorian Poetry: Tennyson, Browning and Rossetti$j$, $j${"questions": [{"q": "A dramatic monologue is:", "options": ["A poem in which a speaker addresses a listener and reveals his character", "A prayer in prose", "A rhymed couplet", "A story told by a crowd"]}, {"q": "In My Last Duchess, the duke reveals:", "options": ["His fear of ghosts", "His kindness", "His pride and cruelty", "His poverty"]}, {"q": "Tennyson's Ulysses ends with the resolve to:", "options": ["Rest forever", "Return home and sleep", "Strive, seek, find and not yield", "Give up"]}, {"q": "An unreliable speaker is one whose words:", "options": ["Are in a letter", "Are in Latin", "Are always correct", "Do not tell the whole truth about himself"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Victorian Poetry: Tennyson, Browning and Rossetti$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,3}'::int[], array[$j$Browning mastered the form.$j$,$j$The reader reads between the lines.$j$,$j$It speaks of perseverance.$j$,$j$The reader must read between the lines.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Victorian Poetry: Tennyson, Browning and Rossetti$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Romantic and Victorian Voices$j$, $j${"questions": [{"q": "Romanticism responded to the Enlightenment by emphasizing:", "options": ["Strict rules", "Emotion and nature", "Military duty", "Technology"]}, {"q": "Lyrical Ballads appeared in:", "options": ["1611", "1914", "1798", "1855"]}, {"q": "Blake's The Tyger asks about:", "options": ["The Maker of the Lamb and the Tyger", "The price of gold", "A ship at sea", "A royal wedding"]}, {"q": "Frankenstein uses:", "options": ["A sonnet", "A frame narrative", "A chorus", "A diary only"]}, {"q": "A main theme of Frankenstein is:", "options": ["Joy of sports", "Responsibility for what we create", "Skill at cooking", "Success in trade"]}, {"q": "Charles Dickens used fiction to:", "options": ["Draw attention to poverty and injustice", "Teach Latin", "Avoid real life", "Write dictionaries"]}, {"q": "A dramatic monologue reveals:", "options": ["The meter", "The author's address", "Only the setting", "The speaker's character"]}, {"q": "Tennyson's Ulysses ends with:", "options": ["A prayer for rest", "A laugh", "Strive, seek, find and not yield", "A farewell to sea"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Romantic and Victorian Voices$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,1,1,0,3,2}'::int[], array[$j$Romantics valued feeling and imagination.$j$,$j$Wordsworth and Coleridge published it in 1798.$j$,$j$The poem wonders at the Creator.$j$,$j$Walton's letters frame Victor's story.$j$,$j$Victor abandons his creation.$j$,$j$He was a social critic.$j$,$j$The speaker reveals himself without meaning to.$j$,$j$It is a call to perseverance.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Romantic and Victorian Voices$j$ on conflict (item_id) do nothing;
